import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        long n = Long.parseLong(parts[0]);
        long t = Long.parseLong(parts[1]);

        long ans;
        if (t == 0) {
            // Apenas 1 rei: ele pode ocupar qualquer uma das N posições (resto peões).
            ans = n;
        } else if (t == 1) {
            // 1 rei e 1 torre: escolhe 2 posições distintas e atribui as peças: N*(N-1).
            ans = n * (n - 1);
        } else {
            // 2 torres e 1 rei: escolhe 3 posições; as extremas são as torres e o rei fica no meio.
            // Total = C(N, 3) = N*(N-1)*(N-2)/6.
            ans = n * (n - 1) * (n - 2) / 6;
        }

        System.out.println(ans);
    }
}
